def legal(path, name, h1, meta, answer, body):
    return dict(path=path, crumbs=[HOME, (name, path)], eyebrow="Legal", h1=h1, title=f"{name} | AL Elite Financing", meta=meta, answer=answer,
                prose=body + "<div class='verify'><strong>Counsel to complete before launch.</strong> This page is a structural placeholder listing the sections a compliant policy needs; it is not legal text.</div>",
                related=[("Privacy policy", "/privacy/"), ("Terms of use", "/terms/"), ("Accessibility", "/accessibility/"), ("Do not sell or share my information", "/do-not-sell/")], form=False, byline=False, noindex=True)

PRIVACY = legal("/privacy/", "Privacy policy", "Privacy policy", "AL Elite Financing privacy policy: what we collect, how we use and share it with lenders, your choices and rights, and how to contact us.",
    "This privacy policy explains what information AL Elite Financing collects when you use our site or submit a request, how we use it, when we share it with lenders and partner contractors, and the choices you have.",
    "<h2>Sections to include</h2><ul><li>Information we collect (form submissions, usage data, cookies)</li><li>How we use it (matching with lenders, communication, improvement)</li><li>When and with whom we share it (lenders, partner contractors, service providers) and that we do not sell personal information</li><li>Your choices (opt out of marketing, texts; access and deletion requests)</li><li>State-specific rights (California and other states with privacy laws)</li><li>Data security and retention</li><li>Children's privacy</li><li>Changes to this policy and contact details</li></ul>")

